/**
 * SIGMA ELMS - Shared UI Component Controllers & Canonical Utilities
 *
 * This file is the single browser entrypoint for reusable UI scripts & core primitives.
 * Page-specific behavior stays in admin.js, teacher.js, or student.js.
 */

// --- CANONICAL UNIVERSAL SCROLL-TO-TOP RESET ---
// Ensures that navigating between pages, tabs, topics, or materials always starts at the top
(function() {
    if (typeof window === 'undefined') return;

    try {
        if ('scrollRestoration' in history) {
            history.scrollRestoration = 'manual';
        }
    } catch (_) {}

    window.sigmaResetScrollToTop = function(target, options = {}) {
        try {
            const behavior = options?.smooth ? 'smooth' : 'instant';

            // 1. Reset browser window & root viewport elements
            if (typeof window.scrollTo === 'function') {
                try {
                    window.scrollTo({ top: 0, left: 0, behavior: behavior });
                } catch (_) {
                    window.scrollTo(0, 0);
                }
            }
            if (document.documentElement && document.documentElement.scrollTop !== 0) {
                document.documentElement.scrollTop = 0;
            }
            if (document.body && document.body.scrollTop !== 0) {
                document.body.scrollTop = 0;
            }

            // 2. Reset explicit target if provided
            if (target) {
                const el = typeof target === 'string' ? document.querySelector(target) : target;
                if (el && typeof el.scrollTop === 'number') {
                    el.scrollTop = 0;
                }
            }

            // 3. Reset all known scroll containers in SIGMA ELMS
            const scrollIds = [
                'main-content',
                'admin-main',
                'student-main',
                'teacher-main',
                'layout-wrapper',
                'classroom-body',
                'topic-content-body',
                'detail-section-topics',
                'subject-topics-container',
                'school-grades-view',
                'users-view',
                'section-topic-content',
                'student-panel-fullscreen-overlay',
                'section-materials-table'
            ];

            scrollIds.forEach(id => {
                const el = document.getElementById(id);
                if (el && el.scrollTop > 0) {
                    el.scrollTop = 0;
                }
            });

            const scrollSelectors = [
                'main',
                '.admin-main',
                '.student-main',
                '.teacher-main',
                '.assessment-material-detail-view',
                '.topic-video-player-view',
                '.topic-page-shell',
                '.topic-content-scroll',
                '.classroom-scroll-container',
                '.topic-overview-body-card',
                '[data-scroll-container]'
            ];

            scrollSelectors.forEach(sel => {
                const elements = document.querySelectorAll(sel);
                elements.forEach(node => {
                    if (node && node.scrollTop > 0) {
                        node.scrollTop = 0;
                    }
                });
            });
        } catch (_) {}
    };

    // Auto-reset scroll on page load, navigation events, and history state changes
    window.addEventListener('load', () => window.sigmaResetScrollToTop?.(), { passive: true });
    window.addEventListener('pageshow', () => window.sigmaResetScrollToTop?.(), { passive: true });
    window.addEventListener('popstate', () => {
        window.sigmaResetScrollToTop?.();
        setTimeout(() => window.sigmaResetScrollToTop?.(), 30);
    }, { passive: true });
    window.addEventListener('hashchange', () => {
        window.sigmaResetScrollToTop?.();
        setTimeout(() => window.sigmaResetScrollToTop?.(), 30);
    }, { passive: true });

    // Universal navigation click delegator
    document.addEventListener('click', (e) => {
        const navTrigger = e.target.closest(
            '.canonical-tab-btn, .canonical-back-btn, .material-detail-back-btn, ' +
            '.nav-link, .nav-sublink, [data-nav-tab], .topic-card, .assessment-row, ' +
            '[data-action="open-topic"], [data-action="back"], .room-quarter-menu__item, ' +
            '.sigma-tab-btn, .tab-btn, a[href^="#"]'
        );
        if (navTrigger) {
            window.sigmaResetScrollToTop?.();
            requestAnimationFrame(() => window.sigmaResetScrollToTop?.());
            setTimeout(() => window.sigmaResetScrollToTop?.(), 30);
            setTimeout(() => window.sigmaResetScrollToTop?.(), 100);
        }
    }, { capture: true, passive: true });
})();

// One empty-state layout: 36px fade icon, 14px/700 title, 12px/500 fade subtitle.
window.renderSigmaEmptyState = function (options) {
    const opts = options || {};
    const icon = opts.icon || 'fa-solid fa-folder-open';
    const title = opts.title || '';
    const subtitle = opts.subtitle || '';
    const className = opts.className ? (' ' + opts.className) : '';
    return ''
        + '<div class="sigma-empty-state' + className + '">'
        + '<i class="' + icon + ' sigma-empty-icon" aria-hidden="true"></i>'
        + '<p class="sigma-empty-title">' + title + '</p>'
        + (subtitle ? '<p class="sigma-empty-subtitle">' + subtitle + '</p>' : '')
        + '</div>';
};

// Canonical Shared Modal Footer (matches release panel, classroom grades panels, and form modals)
window.renderSigmaModalFooter = function (options) {
    const opts = options || {};
    const footerId = opts.footerId ? ' id="' + opts.footerId + '"' : (opts.id ? ' id="' + opts.id + '"' : '');
    const footerClass = opts.footerClass || 'sigma-modal-footer';
    const footerStyle = opts.footerStyle ? ' style="' + opts.footerStyle + '"' : '';

    const showCancel = opts.showCancel !== false && opts.cancelText !== false && opts.cancelText !== null;
    const cancelText = opts.cancelText || 'Close';
    const cancelOnClick = opts.cancelOnClick || '';
    const cancelBtnClass = opts.cancelBtnClass || 'sigma-btn sigma-btn-white sigma-modal-btn';
    const cancelId = opts.cancelId ? ' id="' + opts.cancelId + '"' : '';

    const confirmText = opts.confirmText || '';
    const mobileConfirmText = opts.mobileConfirmText || '';
    const confirmOnClick = opts.confirmOnClick || '';
    const confirmBtnClass = opts.confirmBtnClass || 'sigma-btn sigma-btn-primary sigma-modal-btn';
    const confirmId = opts.confirmId ? ' id="' + opts.confirmId + '"' : '';
    const confirmIcon = opts.confirmIcon || '';
    const confirmIconPosition = opts.confirmIconPosition || 'left';
    const hideIconOnMobile = opts.hideIconOnMobile !== undefined ? opts.hideIconOnMobile : Boolean(mobileConfirmText);
    const extraLeftHtml = opts.extraLeftHtml || '';
    const extraRightHtml = opts.extraRightHtml || '';

    let confirmBtnHtml = '';
    if (confirmText) {
        const iconMobileClass = hideIconOnMobile ? ' sigma-desktop-only' : '';
        const iconHtml = confirmIcon ? '<i class="' + confirmIcon + ' text-xs' + iconMobileClass + '"></i>' : '';
        let labelHtml = '';
        if (mobileConfirmText && mobileConfirmText !== confirmText) {
            labelHtml = '<span class="sigma-desktop-only">' + confirmText + '</span><span class="sigma-mobile-only">' + mobileConfirmText + '</span>';
        } else {
            labelHtml = '<span>' + confirmText + '</span>';
        }

        let inner = '';
        if (confirmIcon && confirmIconPosition === 'left') {
            inner = iconHtml + labelHtml;
        } else if (confirmIcon && confirmIconPosition === 'right') {
            inner = labelHtml + iconHtml;
        } else {
            inner = labelHtml;
        }
        confirmBtnHtml = '<button type="button"' + confirmId + ' class="' + confirmBtnClass + '" onclick="' + confirmOnClick + '">' + inner + '</button>';
    }

    let cancelBtnHtml = '';
    if (extraLeftHtml) {
        cancelBtnHtml = extraLeftHtml;
    } else if (showCancel && cancelText) {
        cancelBtnHtml = '<button type="button"' + cancelId + ' class="' + cancelBtnClass + '" onclick="' + cancelOnClick + '">' + cancelText + '</button>';
    }

    return '<div' + footerId + ' class="' + footerClass + '"' + footerStyle + '>' + cancelBtnHtml + (extraRightHtml ? extraRightHtml : confirmBtnHtml) + '</div>';
};

// Canonical Shared Modal Footer for Subject Editor (matches section-modal-footer and user-modal-footer)
window.renderSubjectModalFooter = function (options) {
    const opts = options || {};
    return window.renderSigmaModalFooter({
        footerId: opts.footerId || 'subject-modal-footer',
        footerClass: opts.footerClass || "sigma-modal-footer flex items-center justify-end gap-3 px-8 sm:px-10 py-4 border-t border-slate-200 bg-white sticky bottom-0 z-30 font-['Inter']",
        footerStyle: opts.footerStyle || "justify-content: flex-end !important;",
        showCancel: false,
        confirmId: opts.confirmId || 'subject-next-btn',
        confirmText: opts.confirmText || 'Next',
        confirmOnClick: opts.confirmOnClick || 'window.handleSubjectNext()',
        confirmBtnClass: opts.confirmBtnClass || "subject-next-btn sigma-btn sigma-btn-primary sigma-btn-md min-w-[120px] cursor-pointer ml-auto flex items-center justify-center gap-2 font-['Inter']",
        confirmIcon: opts.confirmIcon !== undefined ? opts.confirmIcon : 'fa-solid fa-arrow-right',
        confirmIconPosition: 'right'
    });
};

// Global HTML Escaper
window.escapeHtml = function (str) {
    if (str === null || str === undefined) return '';
    return String(str)
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&#39;');
};

// Normalizes internal role names to their display-friendly equivalents.
// "Master Admin" is shown as "Admin" — same tier for display purposes.
window.normalizeRoleDisplay = function (role) {
    if (!role) return role;
    if (role.trim().toLowerCase() === 'master admin') return 'Admin';
    return role;
};

window.ensureAppFavicon = function () {
    if (typeof document === 'undefined') return;
    const head = document.head || document.getElementsByTagName('head')[0];
    if (!head) return;

    const isPhpSubdir = window.location.pathname.includes('/php/');
    const logoPath = isPhpSubdir ? '../image/ICC logo.jpg' : 'image/ICC logo.jpg';

    let link = document.querySelector("link[rel~='icon']");
    if (!link) {
        link = document.createElement('link');
        link.rel = 'icon';
        link.type = 'image/jpeg';
        link.href = logoPath;
        head.appendChild(link);
    } else {
        const currHref = link.getAttribute('href') || '';
        if (!currHref || currHref.endsWith('/favicon.ico') || currHref.includes('about:blank')) {
            link.href = logoPath;
            link.type = 'image/jpeg';
        }
    }
};

(function () {
    window.ensureAppFavicon();
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', window.ensureAppFavicon);
    }
})();

// --- PURGE LEGACY MOCK TOPICS & MATERIALS & ORPHANED RUBRICS ---
(function cleanupAuthorizationLetterAndCrossRubrics() {
    try {
        const cleanObj = (obj) => {
            if (!obj || typeof obj !== 'object') return false;
            let changed = false;
            if (obj.rubricFileName && /authorization[_-]letter/i.test(obj.rubricFileName)) {
                obj.rubricFileName = '';
                obj.rubricUrl = '';
                obj.hasRubric = false;
                obj.rubric = null;
                changed = true;
            }
            if (typeof obj.rubric === 'string' && /authorization[_-]letter/i.test(obj.rubric)) {
                obj.rubric = null;
                obj.hasRubric = false;
                changed = true;
            }
            if (obj.rubric && typeof obj.rubric === 'object' && /authorization[_-]letter/i.test(obj.rubric.fileName || obj.rubric.name || '')) {
                obj.rubric = null;
                obj.hasRubric = false;
                changed = true;
            }
            if (obj.assessmentRubrics && typeof obj.assessmentRubrics === 'object') {
                for (const [k, v] of Object.entries(obj.assessmentRubrics)) {
                    if (/authorization[_-]letter/i.test(String(v?.fileName || v || ''))) {
                        delete obj.assessmentRubrics[k];
                        if (obj.assessmentRubricUrls) delete obj.assessmentRubricUrls[k];
                        if (obj.assessmentRubricFiles) delete obj.assessmentRubricFiles[k];
                        changed = true;
                    }
                }
            }
            if (obj.rubrics && typeof obj.rubrics === 'object') {
                for (const [k, v] of Object.entries(obj.rubrics)) {
                    if (/authorization[_-]letter/i.test(String(v?.fileName || v || ''))) {
                        delete obj.rubrics[k];
                        if (obj.rubricUrls) delete obj.rubricUrls[k];
                        changed = true;
                    }
                }
            }
            if (obj._uploadedRubricName && /authorization[_-]letter/i.test(obj._uploadedRubricName)) {
                delete obj._uploadedRubricName;
                delete obj._uploadedRubricUrl;
                changed = true;
            }
            return changed;
        };

        for (let i = 0; i < localStorage.length; i++) {
            const k = localStorage.key(i);
            if (!k) continue;
            try {
                const raw = localStorage.getItem(k);
                if (raw && (raw.includes('Authorization_Letter') || raw.includes('authorization_letter') || raw.includes('Authorization-Letter'))) {
                    const parsed = JSON.parse(raw);
                    if (Array.isArray(parsed)) {
                        let c = false;
                        parsed.forEach(item => { if (cleanObj(item)) c = true; });
                        if (c) localStorage.setItem(k, JSON.stringify(parsed));
                    } else if (parsed && typeof parsed === 'object') {
                        if (cleanObj(parsed)) {
                            localStorage.setItem(k, JSON.stringify(parsed));
                        }
                    }
                }
            } catch (e) {}
        }
    } catch (e) {}
})();

