window.getUnifiedClassroomTeacher = window.getUnifiedClassroomTeacher || function (sectionName, subjectName) {
    const normSubj = String(subjectName || '').trim().toLowerCase();
    const normSec = String(sectionName || '').trim().toLowerCase();
    const stripGrade = (s) => String(s || '').replace(/^grade\s*\d+\s*[-–]?\s*/i, '').replace(/^g\d+\s*[-–]?\s*/i, '').trim().toLowerCase();
    const baseSec = stripGrade(normSec);

    // 1. Check if admin sections has a teacher configured
    const adminSections = window.getStoredJson('sigma-admin-sections', window.getStoredJson('sigma-sections-list', []));
    if (Array.isArray(adminSections)) {
        let matched = null;
        if (normSubj) {
            matched = adminSections.find(s => {
                if (!s) return false;
                const sName = String(s.name || s.sectionName || s.id || '').trim().toLowerCase();
                const sBase = stripGrade(sName);
                const sSubj = String(s.subject || s.assignedSubject || (Array.isArray(s.assignedSubjects) && s.assignedSubjects[0]) || '').trim().toLowerCase();
                const secMatch = (sName === normSec || sBase === baseSec || sName === String(sectionName).toLowerCase());
                const subjMatch = (sSubj === normSubj || sSubj.includes(normSubj) || normSubj.includes(sSubj));
                return secMatch && subjMatch;
            });
        }
        if (!matched) {
            matched = adminSections.find(s => {
                if (!s) return false;
                const sName = String(s.name || s.sectionName || s.id || '').trim().toLowerCase();
                const sBase = stripGrade(sName);
                return (sName === normSec || sBase === baseSec || (baseSec && sName.includes(baseSec)) || (sBase && normSec.includes(sBase)));
            });
        }
        if (matched) {
            if (Array.isArray(matched.teachers) && matched.teachers.length > 0) {
                const primary = matched.teachers.find(t => t.isPrimary) || matched.teachers[0];
                if (primary) {
                    const pName = typeof primary === 'object' ? (primary.name || primary.fullName) : primary;
                    if (pName) return pName;
                }
            }
            if (matched.teacher) return matched.teacher;
        }
    }

    // 2. Check canonical default subject teachers
    for (const [key, teacher] of Object.entries(DEFAULT_SUBJECT_TEACHERS)) {
        if (normSubj.includes(key) || key.includes(normSubj)) {
            return teacher;
        }
    }

    return 'Alex Reyes';
};

window.submissionSectionKey = function (section) {
    return String(section || '').replace(/^grade\s*\d+\s*[-–]?\s*/i, '').trim().toLowerCase().replace(/[^a-z0-9]+/g, '');
};

window.submissionSectionsMatch = function (a, b) {
    const left = window.submissionSectionKey(a);
    const right = window.submissionSectionKey(b);
    if (!left || !right) return true;
    return left === right;
};

window.quizFileCopyKey = function (studentId, section, subjectId, quizId) {
    const sid = String(studentId || '').trim().toLowerCase().replace(/[^a-z0-9]/g, '');
    const sec = window.submissionSectionKey(section) || 'section';
    const subj = String(subjectId || 'subject').replace(/^(card-|subj-)/, '').trim().toLowerCase().replace(/[^a-z0-9]/g, '');
    const qid = String(quizId || '').trim().toLowerCase().replace(/[^a-z0-9]/g, '');
    if (!sid || !qid) return '';
    return `sigma_student_quiz_file_${sid}_${sec}_${subj}_${qid}`;
};

window.quizFileCopyIds = function (student) {
    if (!student) return [];
    if (typeof student !== 'object') return [String(student)];
    const firstLast = `${student.firstName || ''} ${student.lastName || ''}`.trim();
    const lastFirst = `${student.lastName || ''}, ${student.firstName || ''}`.trim();
    return Array.from(new Set([
        student.id,
        student.studentId,
        student.lrn,
        student.uid,
        student.studentNumber,
        student.name,
        student.fullName,
        student.studentName,
        firstLast,
        lastFirst
    ].filter(Boolean).map(value => String(value).trim()).filter(Boolean)));
};

window.resolveTopicStudentRecord = function (student, section) {
    if (student && typeof student === 'object' && (student.id || student.lrn || student.uid || student.studentNumber)) return student;
    const name = String(typeof student === 'string' ? student : (student?.name || student?.fullName || '')).trim();
    if (!name || name.toLowerCase() === 'all') return student;
    const sec = section || (typeof window.currentTopicState !== 'undefined' && window.currentTopicState?.selectedSection) || '';
    const students = (typeof window.getUnifiedSectionStudents === 'function') ? (window.getUnifiedSectionStudents(sec) || []) : [];
    const curLower = name.toLowerCase();
    const found = students.find(s => {
        if (!s) return false;
        if (typeof s === 'string') return s.trim().toLowerCase() === curLower;
        const sName = String(s.name || s.fullName || '').trim().toLowerCase();
        const lastFirst = (s.lastName && s.firstName) ? `${s.lastName}, ${s.firstName}`.trim().toLowerCase() : '';
        const firstLast = (s.lastName && s.firstName) ? `${s.firstName} ${s.lastName}`.trim().toLowerCase() : '';
        return sName === curLower || lastFirst === curLower || firstLast === curLower
            || (curLower.length > 3 && (sName.includes(curLower) || curLower.includes(sName) || lastFirst.includes(curLower) || curLower.includes(lastFirst) || firstLast.includes(curLower) || curLower.includes(firstLast)));
    });
    if (found && typeof found === 'object') return found;
    if (typeof window.findMatchedUserAccount === 'function') {
        const matched = window.findMatchedUserAccount('', name);
        if (matched) return matched;
    }
    return typeof student === 'object' && student ? student : { id: name, name: name };
};

window.collectQuizAnswerMap = function (record) {
    const merged = {};
    if (!record || typeof record !== 'object') return merged;
    const take = (src) => {
        if (src === undefined || src === null || src === '') return;
        if (Array.isArray(src)) {
            src.forEach((value, index) => {
                if (value !== undefined && value !== null && value !== '' && merged[index] === undefined) merged[index] = value;
            });
            return;
        }
        if (typeof src !== 'object') return;
        Object.keys(src).forEach(key => {
            const value = src[key];
            if (value === undefined || value === null || value === '') return;
            if (merged[key] === undefined) merged[key] = value;
        });
    };
    take(record.userAnswers);
    take(record.answers);
    const harvestQuestionResponses = (questions) => {
        if (!Array.isArray(questions)) return;
        questions.forEach((question, index) => {
            if (!question || typeof question !== 'object') return;
            const value = question.studentAnswer ?? question.userAnswer ?? question.response ?? question.submittedAnswer;
            if (value !== undefined && value !== null && value !== '' && merged[index] === undefined) merged[index] = value;
        });
    };
    harvestQuestionResponses(record.questions);
    if (Array.isArray(record.attempts)) {
        for (let i = record.attempts.length - 1; i >= 0; i--) {
            const attempt = record.attempts[i];
            if (!attempt) continue;
            take(attempt.userAnswers);
            take(attempt.answers);
            harvestQuestionResponses(attempt.questions);
        }
    }
    return merged;
};

window.indexQuizAnswers = function (answers, questions) {
    const src = (answers && typeof answers === 'object') ? answers : {};
    const list = Array.isArray(questions) ? questions : [];
    const out = {};
    const count = Math.max(list.length, Array.isArray(src) ? src.length : 0);
    for (let i = 0; i < (list.length || count); i++) {
        const q = list[i];
        const candidates = [i, String(i), `q-${i + 1}`];
        if (q && q.id !== undefined && q.id !== null && String(q.id) !== String(i) && !/^\d+$/.test(String(q.id))) {
            candidates.push(q.id, String(q.id));
        }
        for (const key of candidates) {
            if (key === undefined || key === null || key === '') continue;
            const value = src[key];
            if (value !== undefined && value !== null && value !== '') {
                out[i] = value;
                break;
            }
        }
    }
    if (!list.length) {
        Object.keys(src).forEach(key => {
            if (out[key] === undefined) out[key] = src[key];
        });
    }
    return out;
};

window.quizQuestionsLookPlaceholder = function (questions) {
    if (!Array.isArray(questions) || !questions.length) return false;
    let hits = 0;
    questions.forEach(question => {
        const text = String(question?.question || question?.title || question?.text || question?.prompt || '').trim();
        const choices = Array.isArray(question?.choices) ? question.choices.map(choice => String(choice).trim()) : [];
        const textHit = /-\s*question\s+\d+$/i.test(text);
        const choiceHit = choices.length >= 4 && choices[0] === 'Option A' && choices[1] === 'Option B' && choices[2] === 'Option C' && choices[3] === 'Option D';
        if (textHit && choiceHit) hits += 1;
    });
    return hits > 0 && hits >= Math.ceil(questions.length * 0.6);
};

window.quizHasRealQuestions = function (questions) {
    return Array.isArray(questions) && questions.length > 0 && !window.quizQuestionsLookPlaceholder(questions);
};

window.cloneQuizQuestionList = function (questions) {
    try {
        return JSON.parse(JSON.stringify(Array.isArray(questions) ? questions : []));
    } catch (e) {
        return Array.isArray(questions) ? questions.slice() : [];
    }
};

window.findStoredQuizFile = function (ids, titles) {
    const clean = (value) => String(value || '').replace(/^#/, '').trim().toLowerCase();
    const idSet = new Set((Array.isArray(ids) ? ids : [ids]).map(clean).filter(value => value && value !== 'null' && value !== 'undefined'));
    const titleList = (Array.isArray(titles) ? titles : [titles]).map(value => String(value || '').trim().toLowerCase()).filter(value => value.length > 2);
    const pools = [];
    const pushList = (list) => { if (Array.isArray(list)) pools.push(list); };
    if (typeof window.getStoredQuizLibrary === 'function') {
        try { pushList(window.getStoredQuizLibrary()); } catch (e) { }
    }
    ['quizzes', 'sigma_quizzes_data', 'sigma_quizzes', 'sigma_quiz_storage', 'sigma-quiz-storage-library', 'quizLibrary', 'sigma_quiz_library'].forEach(key => {
        try {
            const raw = localStorage.getItem(key);
            if (raw) pushList(JSON.parse(raw));
        } catch (e) { }
    });
    const questionListOf = (quiz) => {
        if (!quiz || typeof quiz !== 'object') return null;
        const raw = quiz.questions || quiz.quizQuestions || quiz.questionList;
        if (Array.isArray(raw)) return raw;
        if (typeof raw === 'string' && raw.trim().startsWith('[')) {
            try {
                const parsed = JSON.parse(raw);
                if (Array.isArray(parsed)) return parsed;
            } catch (e) { }
        }
        return null;
    };
    const realQuestions = (quiz) => window.quizHasRealQuestions(questionListOf(quiz));
    const idHit = (quiz) => {
        if (!quiz) return false;
        const quizId = clean(quiz.id);
        const quizCode = clean(quiz.code);
        const selectedId = clean(quiz.selectedQuizId || quiz.quizId);
        return Boolean((quizId && idSet.has(quizId)) || (quizCode && idSet.has(quizCode)) || (selectedId && idSet.has(selectedId)));
    };
    const titleHit = (quiz) => {
        const itemTitle = String(quiz?.title || quiz?.name || quiz?.selectedQuizTitle || quiz?.quizTitle || '').trim().toLowerCase();
        if (!itemTitle || itemTitle.length < 3) return false;
        return titleList.some(title => title === itemTitle || (itemTitle.length > 8 && title.length > 8 && (title.includes(itemTitle) || itemTitle.includes(title))));
    };
    let found = null;
    for (const list of pools) {
        found = list.find(quiz => idHit(quiz) && realQuestions(quiz));
        if (found) return found;
    }
    const subjectKeys = ['sigma-admin-subjects', 'sigma_subjects_v2', 'sigma-teacher-subjects', 'sigma_subjects', 'sigma_subjects_data', 'sigma-student-subjects'];
    for (const key of subjectKeys) {
        try {
            const raw = localStorage.getItem(key);
            if (!raw) continue;
            const subjects = JSON.parse(raw);
            if (!Array.isArray(subjects)) continue;
            for (const subject of subjects) {
                const topics = Array.isArray(subject?.topics) ? subject.topics : [];
                for (const topic of topics) {
                    const buckets = ['assessments', 'quiz', 'quizzes', 'assignments', 'activities'];
                    for (const bucket of buckets) {
                        const items = Array.isArray(topic?.[bucket]) ? topic[bucket] : [];
                        found = items.find(item => item && (idHit(item) || titleHit(item)) && realQuestions(item));
                        if (found) return found;
                    }
                }
            }
        } catch (e) { }
    }
    for (const list of pools) {
        found = list.find(quiz => titleHit(quiz) && realQuestions(quiz));
        if (found) return found;
    }
    const walk = (node, depth) => {
        if (!node || depth > 6) return null;
        if (Array.isArray(node)) {
            for (let i = 0; i < node.length; i++) {
                const nested = walk(node[i], depth + 1);
                if (nested) return nested;
            }
            return null;
        }
        if (typeof node !== 'object') return null;
        if ((idHit(node) || titleHit(node)) && realQuestions(node)) return node;
        const keys = Object.keys(node);
        for (let i = 0; i < keys.length; i++) {
            const child = node[keys[i]];
            if (!child || typeof child !== 'object') continue;
            const nested = walk(child, depth + 1);
            if (nested) return nested;
        }
        return null;
    };
    try {
        for (let i = 0; i < localStorage.length; i++) {
            const key = localStorage.key(i);
            if (!key || key.startsWith('sigma_reset_')) continue;
            const raw = localStorage.getItem(key);
            if (!raw || raw.length < 20 || (raw[0] !== '{' && raw[0] !== '[')) continue;
            let parsed = null;
            try { parsed = JSON.parse(raw); } catch (e) { parsed = null; }
            found = walk(parsed, 0);
            if (found) return found;
        }
    } catch (e) { }
    return null;
};

window.readStudentQuizFileCopy = function (student, section, subjectId, quizId) {
    const ids = window.quizFileCopyIds(student);
    const quizIds = Array.isArray(quizId) ? quizId : [quizId];
    for (const id of ids) {
        for (const qid of quizIds) {
            const key = window.quizFileCopyKey(id, section, subjectId, qid);
            if (!key) continue;
            try {
                const raw = localStorage.getItem(key);
                if (!raw) continue;
                const parsed = JSON.parse(raw);
                if (!parsed || typeof parsed !== 'object') continue;
                if (parsed.studentId && !ids.some(candidate => {
                    const left = String(parsed.studentId).trim().toLowerCase();
                    const right = String(candidate).trim().toLowerCase();
                    return left === right || left.includes(right) || right.includes(left);
                })) continue;
                if (section && parsed.section && !window.submissionSectionsMatch(parsed.section, section)) continue;
                return parsed;
            } catch (e) { }
        }
    }
    const cleanId = (value) => String(value || '').toLowerCase().replace(/[^a-z0-9]/g, '');
    const studentTokens = ids.map(cleanId).filter(Boolean);
    const quizTokens = (Array.isArray(quizId) ? quizId : [quizId]).map(cleanId).filter(token => token.length > 2);
    let bestCopy = null;
    let bestCount = 0;
    try {
        for (let i = 0; i < localStorage.length; i++) {
            const key = localStorage.key(i);
            if (!key) continue;
            const tracked = key.startsWith('sigma_student_quiz_file_') || key.startsWith('sigma_quiz_result_') || key.startsWith('sigma_sub_');
            if (!tracked) continue;
            const keyToken = key.toLowerCase().replace(/[^a-z0-9]/g, '');
            let parsed = null;
            try { parsed = JSON.parse(localStorage.getItem(key) || 'null'); } catch (e) { parsed = null; }
            if (!parsed || typeof parsed !== 'object') continue;
            const studentBlob = `${keyToken} ${String(parsed.studentId || '')} ${String(parsed.studentName || '')} ${String(parsed.student_name || '')}`.toLowerCase().replace(/[^a-z0-9]/g, '');
            if (!studentTokens.some(token => token && studentBlob.includes(token))) continue;
            const quizBlob = `${keyToken} ${JSON.stringify(parsed).toLowerCase().replace(/[^a-z0-9]/g, '')}`;
            if (quizTokens.length && !quizTokens.some(token => quizBlob.includes(token))) continue;
            if (parsed.studentId && !ids.some(candidate => {
                const left = String(parsed.studentId).trim().toLowerCase();
                const right = String(candidate).trim().toLowerCase();
                return left === right || left.includes(right) || right.includes(left);
            })) continue;
            const storedSection = window.submissionSectionKey(parsed.section);
            const viewSection = window.submissionSectionKey(section);
            if (viewSection && storedSection && storedSection !== 'section' && !window.submissionSectionsMatch(parsed.section, section)) continue;
            const count = Object.keys(window.collectQuizAnswerMap(parsed)).length;
            if (count > bestCount) {
                bestCopy = parsed;
                bestCount = count;
            }
        }
    } catch (e) { }
    return bestCopy;
};

window.saveStudentQuizFileCopy = function (copy) {
    if (!copy || typeof copy !== 'object') return '';
    const quizIds = Array.from(new Set([copy.quizId, copy.materialId, copy.id, copy.title].filter(Boolean).map(value => String(value))));
    const studentIds = window.quizFileCopyIds({
        id: copy.studentId,
        studentId: copy.studentId,
        name: copy.studentName,
        fullName: copy.studentName,
        studentName: copy.studentName
    });
    if (copy.studentId) studentIds.unshift(String(copy.studentId));
    const uniqueStudents = Array.from(new Set(studentIds.filter(Boolean)));
    let savedKey = '';
    uniqueStudents.forEach(studentId => {
        quizIds.forEach(quizId => {
            const key = window.quizFileCopyKey(studentId, copy.section, copy.subjectId, quizId);
            if (!key) return;
            const payload = JSON.parse(JSON.stringify(copy));
            payload.studentId = copy.studentId || studentId;
            payload.quizId = copy.quizId || quizId;
            try {
                const existingRaw = localStorage.getItem(key);
                const existing = existingRaw ? JSON.parse(existingRaw) : null;
                const incomingCount = Object.keys(window.collectQuizAnswerMap(payload)).length;
                const existingCount = Object.keys(window.collectQuizAnswerMap(existing)).length;
                if (existing && existingCount > incomingCount) {
                    payload.answers = existing.answers || existing.userAnswers;
                    payload.userAnswers = existing.userAnswers || existing.answers;
                    if (Array.isArray(existing.questions) && existing.questions.length) payload.questions = existing.questions;
                    if (Array.isArray(existing.attempts) && existing.attempts.length) payload.attempts = existing.attempts;
                }
            } catch (e) { }
            localStorage.setItem(key, JSON.stringify(payload));
            savedKey = key;
        });
    });
    return savedKey;
};

window.formatStudentLastFirstMiddle = function formatStudentLastFirstMiddle(student) {
    if (!student) return '';
    const allUsers = (typeof window.getStoredJson === 'function')
        ? window.getStoredJson('sigma-admin-users', window.getStoredJson('sigma-users-list', []))
        : (function () {
            try {
                return JSON.parse(localStorage.getItem('sigma-admin-users')) || JSON.parse(localStorage.getItem('sigma-users-list')) || [];
            } catch (e) { return []; }
        })();

    let stObj = typeof student === 'object' ? student : { name: String(student) };
    let stId = String(stObj.id || stObj.uid || stObj.lrn || '').trim();
    let rawName = String(stObj.name || stObj.fullName || '').trim();

    let lName = String(stObj.lastName || stObj.lastname || '').trim();
    let fName = String(stObj.firstName || stObj.firstname || '').trim();
    let mName = String(stObj.middleName || stObj.middlename || '').trim();

    let matchedUser = null;
    if (Array.isArray(allUsers) && allUsers.length > 0) {
        if (stId) {
            matchedUser = allUsers.find(u => String(u.id || u.uid || u.lrn) === stId);
        }
        if (!matchedUser && rawName) {
            matchedUser = (typeof window.findMatchedUserAccount === 'function')
                ? window.findMatchedUserAccount(stId, rawName)
                : allUsers.find(u => (u.fullName && u.fullName.toLowerCase() === rawName.toLowerCase()) || (u.name && u.name.toLowerCase() === rawName.toLowerCase()));
            if (!matchedUser && typeof window.studentNamesMatch === 'function') {
                matchedUser = allUsers.find(u => window.studentNamesMatch(u.fullName || `${u.lastName}, ${u.firstName}`, rawName));
            }
        }
    }

    if (matchedUser) {
        if (!lName) lName = String(matchedUser.lastName || matchedUser.lastname || '').trim();
        if (!fName) fName = String(matchedUser.firstName || matchedUser.firstname || '').trim();
        if (!mName) mName = String(matchedUser.middleName || matchedUser.middlename || '').trim();
    }

    if (lName && fName) {
        return `${lName}, ${fName}${mName ? ' ' + mName : ''}`;
    }

    if (rawName.includes(',')) {
        return rawName;
    }

    const tokens = rawName.split(/\s+/).filter(Boolean);
    if (tokens.length <= 1) return rawName;

    const compoundLastPrefixes = ['dela', 'delos', 'de la', 'de los', 'san', 'santa', 'del', 'de'];
    if (tokens.length >= 3) {
        const lastTwo = `${tokens[tokens.length - 2]} ${tokens[tokens.length - 1]}`.toLowerCase();
        if (compoundLastPrefixes.some(p => lastTwo.startsWith(p))) {
            const compoundLast = `${tokens[tokens.length - 2]} ${tokens[tokens.length - 1]}`;
            const first = tokens[0];
            const middle = tokens.slice(1, -2).join(' ');
            return `${compoundLast}, ${first}${middle ? ' ' + middle : ''}`;
        }
    }

    const last = tokens[tokens.length - 1];
    const first = tokens[0];
    const middle = tokens.slice(1, -1).join(' ');
    return `${last}, ${first}${middle ? ' ' + middle : ''}`;
};

window.getUnifiedSectionStudents = function (sectionName, subjectName) {
    const stripGrade = (value) => String(value || '').replace(/^grade\s*\d+\s*[-–]?\s*/i, '').trim().toLowerCase();
    const normSec = String(sectionName || '').trim().toLowerCase();
    const normClean = stripGrade(normSec);
    const effSubj = subjectName
        || (typeof currentTopicState !== 'undefined' ? currentTopicState?.subjectId : null)
        || window.currentTopicState?.subjectId
        || (window.currentAdminClassroomSection ? window.currentAdminClassroomSection.subject : null)
        || (typeof currentClassroomKey !== 'undefined' && currentClassroomKey ? currentClassroomKey.split('::')[1] : null)
        || window.currentClassroomSubject
        || '';
    const normSubj = String(effSubj || '').trim().toLowerCase();

    // 1. Check if admin section has students array
    const adminSections = (typeof window.getStoredJson === 'function') ? window.getStoredJson('sigma-admin-sections', []) : [];
    if (Array.isArray(adminSections) && adminSections.length > 0) {
        let matched = null;
        const sectionRecords = adminSections.filter(s => {
            if (!s) return false;
            const sName = String(s.name || s.sectionName || '').trim().toLowerCase();
            const sClean = stripGrade(sName);
            const sId = String(s.id || '').trim().toLowerCase();
            const sGrade = String(s.grade || s.gradeLevel || '').trim().toLowerCase();
            const sFull = `${sGrade} - ${sClean}`.trim();
            return sId === normSec || sName === normSec || sClean === normClean || sFull === normSec;
        });

        if (sectionRecords.length > 0 && normSubj) {
            matched = sectionRecords.find(s => {
                const sSubj = String(s.subject || s.assignedSubject || (Array.isArray(s.assignedSubjects) && s.assignedSubjects[0]) || '').trim().toLowerCase();
                const sCode = String(s.code || s.subjectId || s.subjectCode || '').replace(/^(card-|subj-)/, '').trim().toLowerCase();
                const wantCode = normSubj.replace(/^(card-|subj-)/, '').trim();
                return sSubj === normSubj || (sSubj && normSubj && (sSubj.includes(normSubj) || normSubj.includes(sSubj))) || (sCode && wantCode && sCode === wantCode);
            });
            // If this section exists in adminSections, but DOES NOT offer this requested subject, reject fallthrough
            if (!matched) {
                return [];
            }
        } else if (sectionRecords.length > 0 && !normSubj) {
            matched = sectionRecords[0];
        }

        if (matched && Array.isArray(matched.students)) {
            if (matched.students.length === 0) return [];
            const list = matched.students.map((st, i) => {
                const rawName = typeof st === 'string' ? st : (st.name || st.fullName || `${st.lastName || ''}, ${st.firstName || ''}`.trim());
                const sId = typeof st === 'object' ? (st.id || st.uid || st.lrn || '') : '';
                const u = (typeof window.findMatchedUserAccount === 'function') ? window.findMatchedUserAccount(sId, rawName) : null;
                const formattedName = window.formatStudentLastFirstMiddle(u || st);
                const avatar = (typeof window.resolveUserAvatar === 'function') ? window.resolveUserAvatar(u || st || { id: sId, name: formattedName }) : (u?.avatar || '');
                return {
                    id: u?.id || u?.uid || sId || `STD-${String(i + 1).padStart(3, '0')}`,
                    name: formattedName,
                    fullName: formattedName,
                    displayName: formattedName,
                    firstName: u?.firstName || (typeof st === 'object' ? st.firstName : '') || '',
                    lastName: u?.lastName || (typeof st === 'object' ? st.lastName : '') || '',
                    middleName: u?.middleName || (typeof st === 'object' ? st.middleName : '') || '',
                    avatar: avatar,
                    status: u?.status || (typeof st === 'object' ? st.status : 'Active') || 'Active'
                };
            }).filter(Boolean);
            list.sort((a, b) => String(a.name || '').localeCompare(String(b.name || '')));
            return list;
        }
    }

    // 3. Check if admin users has students
    const adminUsers = (typeof window.getStoredJson === 'function') ? window.getStoredJson('sigma-admin-users', window.getStoredJson('sigma-users-list', [])) : [];
    if (Array.isArray(adminUsers)) {
        const studentUsers = adminUsers.filter(u => {
            if (!String(u.role || u.type || '').toLowerCase().includes('stud') || u.isDeleted) return false;
            if (!normSec) return true;
            const userSec = String(u.section || u.gradeSection || u.sectionName || '').trim().toLowerCase();
            return userSec === normSec || stripGrade(userSec) === normClean;
        });
        if (studentUsers.length > 0) {
            const list = studentUsers.map((u, i) => {
                const displayName = window.formatStudentLastFirstMiddle(u);
                const avatar = (typeof window.resolveUserAvatar === 'function') ? window.resolveUserAvatar(u) : (u.avatar || '');
                return {
                    id: u.id || u.uid || `STD-${String(i + 1).padStart(3, '0')}`,
                    name: displayName,
                    fullName: displayName,
                    displayName: displayName,
                    firstName: u.firstName || '',
                    lastName: u.lastName || '',
                    middleName: u.middleName || '',
                    avatar: avatar,
                    status: u.status || 'Active'
                };
            });
            list.sort((a, b) => String(a.name || '').localeCompare(String(b.name || '')));
            return list;
        }
    }

    const fallbackList = (typeof canonicalDefaultStudents !== 'undefined' && Array.isArray(canonicalDefaultStudents))
        ? canonicalDefaultStudents
        : [...DEFAULT_SECTION_STUDENTS];

    return fallbackList.map(st => {
        const displayName = (typeof window.formatStudentLastFirstMiddle === 'function')
            ? window.formatStudentLastFirstMiddle(st)
            : (typeof st === 'string' ? st : (st.name || st.fullName || ''));
        return {
            ...(typeof st === 'object' ? st : {}),
            name: displayName,
            fullName: displayName,
            displayName: displayName
        };
    }).sort((a, b) => String(a.name || '').localeCompare(String(b.name || '')));
};

window.isUserNameMatch = function (target, user) {
    if (!target || !user) return false;
    const cleanStr = s => String(s || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/[^a-z0-9\s]/g, ' ').replace(/\s+/g, ' ').trim();

    // 1. Direct ID / UID / LRN check if target is an object
    const uId = String(user.id || user.uid || user.lrn || user.employeeId || '').replace(/^#/, '').trim().toLowerCase();
    const uEmail = String(user.email || '').trim().toLowerCase();

    if (typeof target === 'object') {
        const tId = String(target.id || target.uid || target.lrn || target.employeeId || '').replace(/^#/, '').trim().toLowerCase();
        if (tId && uId && tId === uId) return true;
        const tEmail = String(target.email || '').trim().toLowerCase();
        if (tEmail && uEmail && tEmail === uEmail) return true;
        target = target.name || target.fullName || `${target.firstName || ''} ${target.lastName || ''}`;
    }

    const tNorm = cleanStr(target);
    if (!tNorm) return false;
    const ignoreList = ['teacher', 'adviser', 'instructor', 'faculty', 'none', 'n a', 'tba', 'unassigned', 'staff', 'co-teacher', 'lead teacher', 'lead', 'primary', 'student'];
    if (ignoreList.includes(tNorm)) return false;

    // 2. Direct full name comparisons
    const uFull = cleanStr(user.fullName || user.name || `${user.firstName || ''} ${user.lastName || ''}`);
    const uRev = cleanStr(`${user.lastName || ''} ${user.firstName || ''}`);
    if (uFull && (tNorm === uFull || tNorm === uRev)) return true;
    if (uFull && (tNorm.includes(uFull) || uFull.includes(tNorm))) return true;
    if (uRev && (tNorm.includes(uRev) || uRev.includes(tNorm))) return true;

    // 3. Robust First + Last Name Token Matching (ignoring middle names, middle initials, diacritics, and word order)
    const tWords = new Set(tNorm.split(' ').filter(Boolean));

    const uFirstWords = cleanStr(user.firstName || '').split(' ').filter(Boolean);
    let uLastWords = cleanStr(user.lastName || '').split(' ').filter(Boolean);

    if (uFirstWords.length === 0 || uLastWords.length === 0) {
        const allParts = uFull.split(' ').filter(Boolean);
        if (allParts.length >= 2) {
            if (uFirstWords.length === 0) uFirstWords.push(allParts[0]);
            if (uLastWords.length === 0) uLastWords.push(...allParts.slice(1));
        }
    }

    if (uFirstWords.length > 0 && uLastWords.length > 0) {
        const hasFirst = uFirstWords.some(w => tWords.has(w));
        const hasAllLast = uLastWords.every(w => tWords.has(w));
        if (hasFirst && hasAllLast) return true;
    }

    // Also check if target string has first name + last name that match user's words
    const tWordList = tNorm.split(' ').filter(Boolean);
    if (tWordList.length >= 2) {
        const uWordSet = new Set(uFull.split(' ').filter(Boolean));
        const tFirstWord = tWordList[0];
        const tLastWord = tWordList[tWordList.length - 1];
        if (uWordSet.has(tFirstWord) && uWordSet.has(tLastWord)) {
            return true;
        }
    }

    return false;
};

window.isSectionAssignedToTeacher = function (sec, teacher) {
    if (!sec || !teacher) return false;
    const cleanStr = s => String(s || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/[^a-z0-9\s]/g, ' ').replace(/\s+/g, ' ').trim();

    const isMatch = (target) => {
        if (!target) return false;
        if (typeof window.isUserNameMatch === 'function') {
            return window.isUserNameMatch(target, teacher);
        }
        return false;
    };

    // Helper to safely parse array or serialized JSON string
    const getSafeList = (val) => {
        if (!val) return [];
        if (Array.isArray(val)) return val;
        if (typeof val === 'string') {
            try {
                const parsed = JSON.parse(val);
                if (Array.isArray(parsed)) return parsed;
                if (parsed && typeof parsed === 'object') return [parsed];
            } catch (e) {}
            return val.split(',').map(s => s.trim()).filter(Boolean);
        }
        if (typeof val === 'object') return [val];
        return [];
    };

    // 1. Authoritative check: Section Teacher Roster
    let teacherList = [];
    let hasExplicitRoster = false;
    if (sec.teachers !== undefined && sec.teachers !== null) {
        teacherList = getSafeList(sec.teachers);
        hasExplicitRoster = true;
    } else if (sec.assignedTeachers !== undefined && sec.assignedTeachers !== null) {
        teacherList = getSafeList(sec.assignedTeachers);
    }

    teacherList = teacherList
        .concat(getSafeList(sec.coTeachers))
        .concat(getSafeList(sec.instructors));

    if (teacherList.length > 0) {
        const hasTeacher = teacherList.some(t => isMatch(t));
        if (hasTeacher) return true;
        hasExplicitRoster = true;
    }

    // 2. Check sec.teacher / sec.teacherUid / sec.teacherEmail
    const secTeacherUid = String(sec.teacherUid || sec.teacherId || '').toLowerCase().trim();
    const secTeacherEmail = (sec.teacherEmail || '').toLowerCase().trim();
    if (secTeacherUid || secTeacherEmail || sec.teacher) {
        hasExplicitRoster = true;
        if (isMatch({ id: secTeacherUid, email: secTeacherEmail, name: sec.teacher })) {
            return true;
        }
    }

    // 3. Check sec.adviser / sec.leadTeacher / sec.coTeacher / sec.instructor / sec.faculty
    const adviserId = String(sec.adviserId || sec.adviserUid || '').toLowerCase().trim();
    const adviserEmail = (sec.adviserEmail || '').toLowerCase().trim();
    if (adviserId || adviserEmail || sec.adviser || sec.leadTeacher || sec.lead || sec.coTeacher || sec.coteacher || sec.instructor || sec.faculty) {
        hasExplicitRoster = true;
        if (isMatch({ id: adviserId, email: adviserEmail, name: sec.adviser }) ||
            isMatch(sec.leadTeacher) ||
            isMatch(sec.lead) ||
            isMatch(sec.coTeacher) ||
            isMatch(sec.coteacher) ||
            isMatch(sec.instructor) ||
            isMatch(sec.faculty)) {
            return true;
        }
    }

    // If section has an explicit teacher roster defined, and this teacher is NOT in it, do NOT match!
    if (hasExplicitRoster) {
        return false;
    }

    // 4. Fallback ONLY if section has no teacher roster defined at all:
    const secId = String(sec.id || '').toLowerCase().trim();
    const secSubjClean = cleanStr(sec.subject || sec.assignedSubject || (Array.isArray(sec.assignedSubjects) && sec.assignedSubjects[0]) || '');
    const teacherAssignedSubjects = new Set(
        (Array.isArray(teacher.assignedSubjects) ? teacher.assignedSubjects : [])
            .concat(Array.isArray(teacher.subjects) ? teacher.subjects : [])
            .concat(teacher.subject ? [teacher.subject] : [])
            .map(s => cleanStr(typeof s === 'object' ? (s.id || s.name || s.subject) : s))
            .filter(Boolean)
    );

    const assignedSectionIds = new Set(
        (Array.isArray(teacher.assignedSections) ? teacher.assignedSections : [])
            .concat(Array.isArray(teacher.sections) ? teacher.sections : [])
            .map(s => cleanStr(typeof s === 'object' ? (s.id || s.name || s.sectionName) : s))
            .filter(Boolean)
    );

    if (secId && (assignedSectionIds.has(cleanStr(secId)) || assignedSectionIds.has(secId))) {
        if (!secSubjClean || teacherAssignedSubjects.size === 0 || teacherAssignedSubjects.has(secSubjClean)) {
            return true;
        }
    }

    return false;
};

// =============================================================
// GLOBAL USER UPDATE CASCADING & SYNCHRONIZATION
// Propagates updated name/email/ID across all connected sections,
// subjects, user accounts, and authenticated session.
// =============================================================
window.propagateUserUpdateToAllConnected = function (updatedUser, previousUser = null) {
    if (!updatedUser) return;

    const userId = String(updatedUser.id || updatedUser.uid || '').trim();
    const fname = String(updatedUser.firstName || '').trim();
    const mname = String(updatedUser.middleName !== undefined ? updatedUser.middleName : '').trim();
    const lname = String(updatedUser.lastName || '').trim();
    const fullName = (updatedUser.fullName || [fname, mname, lname].filter(Boolean).join(' ')).trim();
    const email = String(updatedUser.email || '').trim();
    const role = String(updatedUser.role || updatedUser.type || '').trim();

    const matchesThisUser = (target) => {
        if (!target) return false;
        if (window.isUserNameMatch(target, updatedUser)) return true;
        if (previousUser && window.isUserNameMatch(target, previousUser)) return true;
        return false;
    };

    // Helper to safely get / save json
    const getList = (key) => {
        try {
            const raw = localStorage.getItem(key);
            if (!raw) return [];
            const parsed = JSON.parse(raw);
            return Array.isArray(parsed) ? parsed : [];
        } catch (e) {
            return [];
        }
    };
    const saveList = (key, list) => {
        try {
            localStorage.setItem(key, JSON.stringify(list));
        } catch (e) {}
    };

    // 1. Update Sections across all section storage keys
    const sectionKeys = ['sigma-admin-sections', 'sigma-sections-list', 'sigma_sections', 'sigma-admin-sections-v1'];
    if (window.SECTIONS_STORAGE_KEY && !sectionKeys.includes(window.SECTIONS_STORAGE_KEY)) {
        sectionKeys.unshift(window.SECTIONS_STORAGE_KEY);
    }

    sectionKeys.forEach(key => {
        const sections = getList(key);
        if (sections.length === 0) return;

        let changed = false;
        sections.forEach(sec => {
            if (!sec) return;

            // sec.teachers
            if (Array.isArray(sec.teachers)) {
                sec.teachers.forEach((t, idx) => {
                    if (matchesThisUser(t)) {
                        if (typeof t === 'object') {
                            t.id = userId || t.id;
                            t.uid = userId || t.uid;
                            t.name = fullName;
                            t.fullName = fullName;
                            t.firstName = fname || t.firstName;
                            t.middleName = mname;
                            t.lastName = lname || t.lastName;
                            t.email = email || t.email;
                        } else {
                            sec.teachers[idx] = {
                                id: userId,
                                uid: userId,
                                name: fullName,
                                fullName: fullName,
                                firstName: fname,
                                middleName: mname,
                                lastName: lname,
                                email: email,
                                role: sec.role || 'Teacher'
                            };
                        }
                        changed = true;
                    }
                });
            }

            // sec.assignedTeachers
            if (Array.isArray(sec.assignedTeachers)) {
                sec.assignedTeachers.forEach((t, idx) => {
                    if (matchesThisUser(t)) {
                        if (typeof t === 'object') {
                            t.id = userId || t.id;
                            t.uid = userId || t.uid;
                            t.name = fullName;
                            t.fullName = fullName;
                            t.firstName = fname || t.firstName;
                            t.middleName = mname;
                            t.lastName = lname || t.lastName;
                            t.email = email || t.email;
                        } else {
                            sec.assignedTeachers[idx] = fullName;
                        }
                        changed = true;
                    }
                });
            }

            // sec.coTeachers
            if (Array.isArray(sec.coTeachers)) {
                sec.coTeachers.forEach((t, idx) => {
                    if (matchesThisUser(t)) {
                        if (typeof t === 'object') {
                            t.id = userId || t.id;
                            t.uid = userId || t.uid;
                            t.name = fullName;
                            t.fullName = fullName;
                            t.email = email || t.email;
                        } else {
                            sec.coTeachers[idx] = fullName;
                        }
                        changed = true;
                    }
                });
            }

            // sec.instructors
            if (Array.isArray(sec.instructors)) {
                sec.instructors.forEach((t, idx) => {
                    if (matchesThisUser(t)) {
                        if (typeof t === 'object') {
                            t.id = userId || t.id;
                            t.uid = userId || t.uid;
                            t.name = fullName;
                            t.fullName = fullName;
                            t.email = email || t.email;
                        } else {
                            sec.instructors[idx] = fullName;
                        }
                        changed = true;
                    }
                });
            }

            // sec.teacher
            if (matchesThisUser(sec.teacher) || (sec.teacherId && sec.teacherId === userId)) {
                sec.teacher = fullName;
                sec.teacherId = userId || sec.teacherId;
                sec.teacherUid = userId || sec.teacherUid;
                if (email) sec.teacherEmail = email;
                changed = true;
            }

            // sec.adviser
            if (matchesThisUser(sec.adviser) || (sec.adviserId && sec.adviserId === userId)) {
                sec.adviser = fullName;
                sec.adviserId = userId || sec.adviserId;
                sec.adviserUid = userId || sec.adviserUid;
                if (email) sec.adviserEmail = email;
                changed = true;
            }

            // sec.leadTeacher
            if (matchesThisUser(sec.leadTeacher)) {
                sec.leadTeacher = fullName;
                changed = true;
            }

            // sec.coTeacher
            if (matchesThisUser(sec.coTeacher)) {
                sec.coTeacher = fullName;
                changed = true;
            }

            // sec.students / enrolledStudents / studentRoster
            ['students', 'assignedStudents', 'enrolledStudents', 'studentRoster'].forEach(studentField => {
                if (Array.isArray(sec[studentField])) {
                    sec[studentField].forEach((st, idx) => {
                        if (matchesThisUser(st)) {
                            if (typeof st === 'object') {
                                st.id = userId || st.id;
                                st.uid = userId || st.uid;
                                st.name = fullName;
                                st.fullName = fullName;
                                st.firstName = fname || st.firstName;
                                st.middleName = mname;
                                st.lastName = lname || st.lastName;
                                st.email = email || st.email;
                            } else {
                                sec[studentField][idx] = fullName;
                            }
                            changed = true;
                        }
                    });
                }
            });
        });

        if (changed) {
            saveList(key, sections);
        }
    });

    // 2. Update Subjects across all subject storage keys
    const subjectKeys = ['sigma-admin-subjects', 'sigma-subjects-list', 'sigma_subjects'];
    if (window.SUBJECTS_STORAGE_KEY && !subjectKeys.includes(window.SUBJECTS_STORAGE_KEY)) {
        subjectKeys.unshift(window.SUBJECTS_STORAGE_KEY);
    }

    subjectKeys.forEach(key => {
        const subjects = getList(key);
        if (subjects.length === 0) return;

        let changed = false;
        subjects.forEach(subj => {
            if (!subj) return;
            if (Array.isArray(subj.teachers)) {
                subj.teachers.forEach((t, idx) => {
                    if (matchesThisUser(t)) {
                        if (typeof t === 'object') {
                            t.id = userId || t.id;
                            t.name = fullName;
                            t.email = email || t.email;
                        } else {
                            subj.teachers[idx] = fullName;
                        }
                        changed = true;
                    }
                });
            }
            if (matchesThisUser(subj.teacher)) {
                subj.teacher = fullName;
                changed = true;
            }
            if (Array.isArray(subj.assignedTeachers)) {
                subj.assignedTeachers.forEach((t, idx) => {
                    if (matchesThisUser(t)) {
                        if (typeof t === 'object') {
                            t.id = userId || t.id;
                            t.name = fullName;
                            t.email = email || t.email;
                        } else {
                            subj.assignedTeachers[idx] = fullName;
                        }
                        changed = true;
                    }
                });
            }
        });

        if (changed) {
            saveList(key, subjects);
        }
    });

    // 3. Update User lists across all user storage keys
    const userKeys = ['sigma-admin-users', 'sigma-users-list', 'sigma-teacher-users', 'sigma-student-users', 'sigma-users', 'sigma-teacher-users-v1'];
    if (window.USER_STORAGE_KEY && !userKeys.includes(window.USER_STORAGE_KEY)) {
        userKeys.unshift(window.USER_STORAGE_KEY);
    }

    userKeys.forEach(key => {
        const users = getList(key);
        if (users.length === 0) return;

        let changed = false;
        users.forEach(u => {
            if (matchesThisUser(u)) {
                u.id = userId || u.id;
                u.uid = userId || u.uid;
                u.firstName = fname || u.firstName;
                u.middleName = mname;
                u.lastName = lname || u.lastName;
                u.fullName = fullName;
                u.name = fullName;
                if (updatedUser.gender !== undefined) u.gender = updatedUser.gender;
                if (email) u.email = email;
                if (role) {
                    u.role = role;
                    u.type = role.toUpperCase();
                }
                changed = true;
            }
        });

        if (changed) {
            saveList(key, users);
        }
    });

    // 4. Update session storage & logged-in user
    try {
        const authRaw = sessionStorage.getItem('sigma-authenticated-user');
        if (authRaw) {
            const auth = JSON.parse(authRaw);
            if (matchesThisUser(auth)) {
                auth.id = userId || auth.id;
                auth.uid = userId || auth.uid;
                auth.firstName = fname || auth.firstName;
                auth.middleName = mname;
                auth.lastName = lname || auth.lastName;
                auth.fullName = fullName;
                auth.name = fullName;
                if (updatedUser.gender !== undefined) auth.gender = updatedUser.gender;
                if (email) auth.email = email;
                sessionStorage.setItem('sigma-authenticated-user', JSON.stringify(auth));
            }
        }
    } catch (e) {}

    try {
        const curRaw = sessionStorage.getItem('currentUser');
        if (curRaw) {
            const cur = JSON.parse(curRaw);
            if (matchesThisUser(cur)) {
                cur.id = userId || cur.id;
                cur.uid = userId || cur.uid;
                cur.firstName = fname || cur.firstName;
                cur.middleName = mname;
                cur.lastName = lname || cur.lastName;
                cur.fullName = fullName;
                cur.name = fullName;
                if (updatedUser.gender !== undefined) cur.gender = updatedUser.gender;
                if (email) cur.email = email;
                sessionStorage.setItem('currentUser', JSON.stringify(cur));
            }
        }
    } catch (e) {}

    try {
        const logRaw = localStorage.getItem('sigma-logged-in-user');
        if (logRaw) {
            const logU = JSON.parse(logRaw);
            if (matchesThisUser(logU)) {
                logU.id = userId || logU.id;
                logU.uid = userId || logU.uid;
                logU.firstName = fname || logU.firstName;
                logU.middleName = mname;
                logU.lastName = lname || logU.lastName;
                logU.fullName = fullName;
                if (email) logU.email = email;
                localStorage.setItem('sigma-logged-in-user', JSON.stringify(logU));
            }
        }
    } catch (e) {}

    // Invalidate cached teacher cards so UI updates immediately
    window._cachedTeacherSectionCards = null;
    window._cachedTeacherSectionCardsTime = 0;
    window.dispatchEvent(new CustomEvent('sigma:user-profile-updated', { detail: { userId } }));
};

// Global startup healer: automatically syncs existing users to existing sections
window.syncAllConnectedUserRecords = function () {
    try {
        const rawUsers = localStorage.getItem('sigma-admin-users') || localStorage.getItem('sigma-users-list');
        if (!rawUsers) return;
        const users = JSON.parse(rawUsers);
        if (!Array.isArray(users)) return;

        users.forEach(u => {
            if (u && (u.id || u.uid) && (u.fullName || u.firstName)) {
                window.propagateUserUpdateToAllConnected(u);
            }
        });
    } catch (e) {}
};

// Auto-run on load
if (typeof document !== 'undefined') {
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', () => {
            window.syncAllConnectedUserRecords();
        });
    } else {
        window.syncAllConnectedUserRecords();
    }
}

window.isSectionAssignedToStudent = function (sec, student) {
    if (!sec || !student) return false;
    const cleanStr = s => String(s || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/[^a-z0-9\s]/g, ' ').replace(/\s+/g, ' ').trim();

    const studentId = String(student.uid || student.id || student.lrn || '').toLowerCase().trim();
    const studentLrn = String(student.lrn || '').trim();
    const studentEmail = String(student.email || '').toLowerCase().trim();
    const studentFullName = cleanStr(student.fullName || student.name || `${student.firstName || ''} ${student.lastName || ''}`);
    const studentRevName = cleanStr(`${student.lastName || ''} ${student.firstName || ''}`);
    const nameParts = studentFullName.split(' ').filter(Boolean);
    const studentFirst = cleanStr(student.firstName || nameParts[0] || '');
    const studentLast = cleanStr(student.lastName || nameParts.slice(1).join(' ') || '');

    const isNameMatch = (targetName) => {
        if (!targetName) return false;
        if (typeof targetName === 'object') {
            targetName = targetName.name || targetName.fullName || `${targetName.firstName || ''} ${targetName.lastName || ''}`;
        }
        const tNorm = cleanStr(targetName);
        if (!tNorm) return false;
        if (studentFullName && (tNorm === studentFullName || tNorm === studentRevName)) return true;
        if (studentFullName && (tNorm.includes(studentFullName) || studentFullName.includes(tNorm))) return true;
        if (studentRevName && (tNorm.includes(studentRevName) || studentRevName.includes(tNorm))) return true;
        if (studentFirst && studentLast && studentFirst.length >= 2 && studentLast.length >= 2) {
            const words = new Set(tNorm.split(' '));
            if (words.has(studentFirst) && words.has(studentLast)) return true;
        }
        if (nameParts.length >= 2) {
            const tWords = new Set(tNorm.split(' '));
            if (nameParts.every(w => tWords.has(w))) return true;
        }
        return false;
    };

    const secId = String(sec.id || '').toLowerCase().trim();
    const secNameClean = cleanStr(sec.name || sec.sectionName || sec.section || '');

    // 1. Check student profile section / enrolledSections / assignedSections / sections
    const studentSections = new Set(
        (Array.isArray(student.enrolledSections) ? student.enrolledSections : [])
            .concat(Array.isArray(student.assignedSections) ? student.assignedSections : [])
            .concat(Array.isArray(student.sections) ? student.sections : [])
            .concat(student.section ? [student.section] : [])
            .map(s => cleanStr(typeof s === 'object' ? (s.id || s.name || s.sectionName) : s))
            .filter(Boolean)
    );
    if (secId && (studentSections.has(cleanStr(secId)) || studentSections.has(secId))) return true;
    if (secNameClean && (studentSections.has(cleanStr(secNameClean)) || studentSections.has(secNameClean))) return true;

    // Helper to safely parse array or serialized JSON string
    const getSafeList = (val) => {
        if (!val) return [];
        if (Array.isArray(val)) return val;
        if (typeof val === 'string') {
            try {
                const parsed = JSON.parse(val);
                if (Array.isArray(parsed)) return parsed;
                if (parsed && typeof parsed === 'object') return [parsed];
            } catch (e) {}
            return val.split(',').map(s => s.trim()).filter(Boolean);
        }
        if (typeof val === 'object') return [val];
        return [];
    };

    // 2. Check sec.students, sec.enrolledStudents, sec.classmates
    const studentList = getSafeList(sec.students)
        .concat(getSafeList(sec.enrolledStudents))
        .concat(getSafeList(sec.classmates));

    if (studentList.length > 0) {
        const hasStudent = studentList.some(st => {
            if (!st) return false;
            if (typeof window.isUserNameMatch === 'function') {
                return window.isUserNameMatch(st, student);
            }
            if (typeof st === 'string') {
                return (studentId && cleanStr(st) === studentId) || isNameMatch(st);
            }
            const stId = String(st.id || st.uid || st.lrn || '').toLowerCase().trim();
            if (stId && studentId && (stId === studentId || (studentLrn && stId === studentLrn.toLowerCase()))) return true;

            const stLrn = String(st.lrn || '').trim();
            if (stLrn && studentLrn && stLrn === studentLrn) return true;

            const stEmail = String(st.email || '').toLowerCase().trim();
            if (stEmail && studentEmail && stEmail === studentEmail) return true;

            const stName = st.name || st.fullName || `${st.firstName || ''} ${st.lastName || ''}`;
            return isNameMatch(stName);
        });
        if (hasStudent) return true;
    }

    return false;
};

window.checkIsSectionAdviser = function (teacherName, sectionName) {
    if (!teacherName || !sectionName) return false;
    const cleanTeacher = String(teacherName).trim().toLowerCase();
    const cleanSection = String(sectionName).trim().toLowerCase();

    // Normalize section names by removing grade prefixes (e.g., "Grade 11 - Rizal" -> "rizal")
    const stripGrade = (s) => s.replace(/^grade\s*\d+\s*[-–]?\s*/i, '').replace(/^g\d+\s*[-–]?\s*/i, '').trim().toLowerCase();
    const baseSection = stripGrade(cleanSection);

    const adminSections = (typeof window.getStoredJson === 'function')
        ? window.getStoredJson('sigma-admin-sections', window.getStoredJson('sigma-sections-list', []))
        : (JSON.parse(localStorage.getItem('sigma-admin-sections') || '[]'));

    if (Array.isArray(adminSections) && adminSections.length > 0) {
        for (const sec of adminSections) {
            const secName = String(sec.name || '').trim().toLowerCase();
            const secBase = stripGrade(secName);
            const secCode = String(sec.code || '').trim().toLowerCase();
            const secId = String(sec.id || '').trim().toLowerCase();

            const matchesSec = (
                secName === cleanSection ||
                secBase === baseSection ||
                (baseSection.length > 2 && secBase.includes(baseSection)) ||
                (secBase.length > 2 && baseSection.includes(secBase)) ||
                (secCode && (secCode === cleanSection || secCode === baseSection)) ||
                (secId && (secId === cleanSection || secId === baseSection))
            );

            if (matchesSec) {
                // 1. Check sec.teachers list (Configured in Admin Section Modal)
                if (Array.isArray(sec.teachers) && sec.teachers.length > 0) {
                    const matchedTeacher = sec.teachers.find(t => {
                        const tName = String(t.name || t.fullName || '').trim().toLowerCase();
                        return (tName.includes(cleanTeacher) || cleanTeacher.includes(tName));
                    });
                    if (matchedTeacher) {
                        return String(matchedTeacher.role || '').trim().toLowerCase() === 'adviser' || Boolean(matchedTeacher.isAdviser);
                    }
                }

                // 2. Check sec.adviser property (explicit adviser field)
                const adviserName = String(sec.adviser || sec.adviserName || '').trim().toLowerCase();
                if (adviserName && (adviserName.includes(cleanTeacher) || cleanTeacher.includes(adviserName))) {
                    return true;
                }

                // 3. Check single teacher property if role is explicitly Adviser
                if (sec.teacher && String(sec.role || '').trim().toLowerCase() === 'adviser') {
                    const tName = String(sec.teacher).trim().toLowerCase();
                    if (tName.includes(cleanTeacher) || cleanTeacher.includes(tName)) {
                        return true;
                    }
                }

                // Section matched, but teacher was not assigned as Adviser
                return false;
            }
        }
    }

    return false;
};

// --- CANONICAL SHARED ROOM MEMBERS TAB COMPONENT ---
// Renders the exact identical Members / People tab in both Teacher and Student Section Rooms
window.resolveRoomFacultyPanels = function (options = {}) {
    const personName = (t) => {
        if (!t) return '';
        if (typeof t === 'string') return t.trim();
        return String(t.name || t.fullName || `${t.firstName || ''} ${t.lastName || ''}`).trim();
    };
    const nameKey = (n) => String(n || '').toLowerCase().replace(/\s+/g, ' ').trim();
    const classifyRole = (t) => {
        const role = String((t && typeof t === 'object') ? (t.role || '') : '').toLowerCase();
        if (role.includes('co-teacher') || role.includes('co teacher') || role.includes('coteacher')) return 'coteacher';
        if (role.includes('advis')) return 'adviser';
        return 'teacher';
    };

    let raw = Array.isArray(options.teachers) ? options.teachers.filter(Boolean) : [];
    const sectionName = options.section || options.sectionName || '';
    const subjectName = options.subject || '';
    const normSubj = String(subjectName).trim().toLowerCase();
    const normSec = String(sectionName).trim().toLowerCase();
    const stripGrade = (s) => String(s || '').replace(/^grade\s*\d+\s*[-–]?\s*/i, '').replace(/^g\d+\s*[-–]?\s*/i, '').trim().toLowerCase();
    const baseSec = stripGrade(normSec);
    const adminSections = (typeof window.getStoredJson === 'function')
        ? window.getStoredJson('sigma-admin-sections', window.getStoredJson('sigma-sections-list', []))
        : [];
    let matched = null;
    if (Array.isArray(adminSections)) {
        if (normSubj) {
            matched = adminSections.find(s => {
                if (!s) return false;
                const sName = String(s.name || s.sectionName || '').trim().toLowerCase();
                const sSubj = String(s.subject || s.assignedSubject || (Array.isArray(s.assignedSubjects) && s.assignedSubjects[0]) || '').trim().toLowerCase();
                const secMatch = sName === normSec || stripGrade(sName) === baseSec;
                const subjMatch = sSubj && (sSubj === normSubj || sSubj.includes(normSubj) || normSubj.includes(sSubj));
                return secMatch && subjMatch;
            });
        }
        if (!matched && !normSubj && normSec) {
            matched = adminSections.find(s => {
                if (!s) return false;
                const sName = String(s.name || s.sectionName || '').trim().toLowerCase();
                return sName === normSec || stripGrade(sName) === baseSec;
            });
        }
    }
    if (!raw.length && matched) {
        if (Array.isArray(matched.teachers) && matched.teachers.length) raw = matched.teachers.slice();
        else if (matched.teacher) {
            raw = [{
                name: matched.teacher,
                role: matched.role || (matched.adviser === matched.teacher ? 'Adviser' : 'Teacher'),
                isPrimary: true
            }];
        }
    }
    if (matched && matched.adviser) {
        const adviserName = personName(matched.adviser);
        if (adviserName && !raw.some(t => nameKey(personName(t)) === nameKey(adviserName))) {
            raw.push({ name: adviserName, role: 'Adviser', isPrimary: false });
        }
    }
    if (!raw.length) {
        const fallback = options.teacherName || (typeof window.getUnifiedClassroomTeacher === 'function'
            ? window.getUnifiedClassroomTeacher(sectionName, subjectName)
            : '');
        if (fallback && !String(fallback).includes(',')) raw = [{ name: fallback, role: 'Teacher', isPrimary: true }];
    }

    const people = [];
    const seen = new Set();
    raw.forEach(t => {
        const name = personName(t);
        const key = nameKey(name);
        if (!name || seen.has(key)) return;
        seen.add(key);
        people.push({
            name,
            role: classifyRole(t),
            isPrimary: Boolean(t && typeof t === 'object' && t.isPrimary)
        });
    });

    const primary = people.find(p => p.isPrimary)
        || people.find(p => p.role === 'teacher')
        || people[0]
        || null;
    const teachers = [];
    const pushTeacher = (person) => {
        if (!person || teachers.some(item => nameKey(item.name) === nameKey(person.name))) return;
        teachers.push(person);
    };
    if (primary) pushTeacher(primary);
    people.forEach(pushTeacher);
    teachers.forEach(person => {
        person.badge = person.role === 'adviser' ? 'Adviser' : '';
    });

    return { teachers };
};

window.renderRoomMembersTabContent = function (options = {}) {
    let rawStudents = options.students;
    if (!rawStudents || rawStudents.length === 0) {
        rawStudents = window.getUnifiedSectionStudents(options.section || options.sectionName, options.subject);
    }
    const role = options.role || 'teacher';
    const studentsTitle = role === 'student' ? 'Classmates' : 'Students';
    const faculty = (typeof window.resolveRoomFacultyPanels === 'function')
        ? window.resolveRoomFacultyPanels(options)
        : { teachers: [] };

    const memberCardHtml = (person) => {
        const personName = person.name || '';
        const safeName = String(personName).replace(/'/g, "\\'");
        const avatarHtml = (typeof window.renderUserAvatarHtml === 'function')
            ? window.renderUserAvatarHtml(personName, 'md')
            : `<div class="sigma-user-avatar sigma-user-avatar--md"><i class="fa-solid fa-user text-sm"></i></div>`;
        const badgeHtml = person.badge
            ? `<span class="member-role-badge">${person.badge}</span>`
            : '';
        return `
        <div onclick="window.openUserProfile && window.openUserProfile('${safeName}')"
            class="member-card-bubble">
            ${avatarHtml}
            <div class="min-w-0 flex-1">
                <p class="member-name-text text-sm font-medium text-black tracking-tight truncate font-['Inter']">${personName}</p>
            </div>
            ${badgeHtml}
        </div>`;
    };

    const facultyPanelHtml = (title, people) => {
        if (!people || !people.length) return '';
        return `
                <div>
                    <div class="member-section-header flex items-center justify-between pb-3 mb-4 border-b border-black/[0.08]">
                        <h3 class="text-xl font-bold text-black font-['Inter']">${title}</h3>
                    </div>
                    <div class="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-3.5">
                        ${people.map(p => memberCardHtml(p)).join('')}
                    </div>
                </div>`;
    };

    // Normalize and format students array with full Last, First Middle name
    const studentList = (Array.isArray(rawStudents) ? rawStudents : []).map(s => {
        const formattedName = (typeof window.formatStudentLastFirstMiddle === 'function')
            ? window.formatStudentLastFirstMiddle(s)
            : (typeof s === 'string' ? s : (s.name || s.fullName || ''));
        if (typeof s === 'string') return { name: formattedName, fullName: formattedName };
        return { ...s, name: formattedName, fullName: formattedName };
    }).filter(s => s && s.name);

    const classmatesCardsHtml = [...studentList]
        .sort((a, b) => a.name.localeCompare(b.name))
        .map(student => {
            const displayName = student.name;
            const studentAvatarHtml = (typeof window.renderUserAvatarHtml === 'function')
                ? window.renderUserAvatarHtml(displayName, 'md')
                : `<div class="sigma-user-avatar sigma-user-avatar--md"><i class="fa-solid fa-user text-sm"></i></div>`;

            return `
            <div onclick="window.openUserProfile && window.openUserProfile('${displayName.replace(/'/g, "\\'")}')"
                class="member-card-bubble">
                ${studentAvatarHtml}
                <div class="min-w-0 flex-1">
                    <p class="member-name-text text-sm font-medium text-black tracking-tight truncate font-['Inter']">${displayName}</p>
                </div>
            </div>`;
        }).join('');

    return `
    <div class="room-people-tab-content font-['Inter']">
        <div class="room-people-tab-left">
            <div class="room-people-panel-container bg-white rounded-2xl md:rounded-[22px] border border-[#e2e8f0] p-6 sm:p-8 space-y-8">
                ${facultyPanelHtml('Teacher', faculty.teachers || [])}

                <!-- Students / Classmates Section -->
                <div>
                    <div class="member-section-header flex items-center justify-between pb-3 mb-4 border-b border-black/[0.08]">
                        <div class="flex items-center gap-3">
                            <h3 class="text-xl font-bold text-black font-['Inter']">${studentsTitle}</h3>
                            <span class="text-sm font-normal text-black/50">${studentList.length} students</span>
                        </div>
                    </div>
                    <div class="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-3.5">
                        ${classmatesCardsHtml}
                    </div>
                </div>
            </div>
        </div>
    </div>`;
};

