window.getTopicOverview = function (title) {
    return _TOPIC_OVERVIEWS[title] || 'This topic covers key concepts and practical applications essential to mastering this subject.';
};

window.getCircleProgressColor = function (pct) {
    const val = Math.min(100, Math.max(0, Number(pct) || 0));
    if (val === 0) return '#94a3b8'; // Slate/gray for 0%
    if (val < 30) return '#ef4444';  // Red (1% - 29%)
    if (val < 50) return '#f97316';  // Orange (30% - 49%)
    if (val < 75) return '#eab308';  // Amber/Yellow (50% - 74%)
    if (val < 90) return '#16a34a';  // Vibrant Green (75% - 89%)
    return '#15803d';                // Institutional Green (90% - 100%)
};

